namespace ghidra.app.plugin.core.string.translate;

using static ghidra.program.model.data.TranslationSettingsDefinition;



using docking.action;
using ghidra.program.model.data;
using ghidra.program.model.listing;
using ghidra.program.model.listing;
using ghidra.program.util;
using ghidra.program.util;
using ghidra.util;
using ghidra.util.task;
